<?php
declare(strict_types=1);
require_once __DIR__.'/ayo-os.php';
/** A scoped polling bridge: public company research in, review-only proposals out. */
final class LifeOpportunityAgents {
 public function __construct(private LifeAyoOS $os,private mixed $clock=null){if(!$this->os->store->db->inTransaction())$this->os->store->db->exec(file_get_contents(__DIR__.'/migrations/opportunity-agents.sql'));}
 private function time():int{return $this->clock?($this->clock)():time();}
 private function at(?int $time=null):string{return gmdate('Y-m-d\TH:i:s\Z',$time??$this->time());}
 private function transaction(callable $f):mixed{$db=$this->os->store->db;$owns=!$db->inTransaction();if($owns)$db->beginTransaction();try{$out=$f();if($owns)$db->commit();return $out;}catch(Throwable $e){if($owns&&$db->inTransaction())$db->rollBack();throw $e;}}
 public function handleOwner(string $action,array $args):array {
  LifeAyoOS::requireWorkspace($args,$this->os->store->tenantId);$action=substr($action,strrpos('.'.$action,'.'));$db=$this->os->store->db;$tenant=$this->os->store->tenantId;
  if($action==='status')return $this->status();
  if($action==='queue')return $this->queue($args);
  if(in_array($action,['token','revoke'],true)){
   if(($args['confirm']??false)!==true)throw new LifeError('Explicitly confirm this research-only connection change.',403);
   return $this->transaction(function()use($action,$db,$tenant){$at=$this->at();$db->prepare('UPDATE life_opportunity_agent_tokens SET revoked_at=? WHERE tenant_id=? AND revoked_at=?')->execute([$at,$tenant,'']);if($action==='revoke')return ['revoked'=>true,'notice'=>'Research connection revoked. Existing proposals remain for review.'];$token=bin2hex(random_bytes(32));$expires=$this->at($this->time()+90*86400);$db->prepare('INSERT INTO life_opportunity_agent_tokens VALUES (?,?,?,?,?,?)')->execute([hash('sha256',$token),$tenant,$at,$expires,'','']);return ['token'=>$token,'expiresAt'=>$expires,'scope'=>'public-research:claim public-research:propose','notice'=>'Shown once. Store only in n8n credentials. This cannot read mail, CVs or change Life records.'];});
  }
  if($action==='review'){
   $id=LifeApplications::id($args['jobId']??'');$decision=$args['decision']??'';if(!in_array($decision,['reviewed','rejected'],true))throw new LifeError('Choose reviewed or rejected.');$q=$db->prepare('UPDATE life_opportunity_agent_jobs SET status=?,reviewed_at=? WHERE tenant_id=? AND id=? AND status IN (?,?,?)');$q->execute([$decision,$this->at(),$tenant,$id,'completed','reviewed','rejected']);if($q->rowCount()===0){$find=$db->prepare('SELECT status FROM life_opportunity_agent_jobs WHERE tenant_id=? AND id=?');$find->execute([$tenant,$id]);$row=$find->fetchColumn();if(!$row)throw new LifeError('This research result is unavailable.',404);if($row!==$decision)throw new LifeError('Wait for research to finish before reviewing.',409);}return ['jobId'=>$id,'status'=>$decision,'notice'=>'Review recorded. No company, application, email or document was changed.'];
  }
  throw new LifeError('This research action is unavailable.',400);
 }
 public function status():array {
  $db=$this->os->store->db;$tenant=$this->os->store->tenantId;$q=$db->prepare('SELECT expires_at,last_seen FROM life_opportunity_agent_tokens WHERE tenant_id=? AND revoked_at=? AND expires_at>? ORDER BY created_at DESC');$q->execute([$tenant,'',$this->at()]);$tokens=$q->fetchAll(PDO::FETCH_ASSOC);$last='';foreach($tokens as$t)if($t['last_seen']>$last)$last=$t['last_seen'];$counts=[];$q=$db->prepare('SELECT status,COUNT(*) AS count FROM life_opportunity_agent_jobs WHERE tenant_id=? GROUP BY status');$q->execute([$tenant]);foreach($q->fetchAll(PDO::FETCH_ASSOC)as$r)$counts[$r['status']]=(int)$r['count'];$q=$db->prepare('SELECT id,pipeline,query_text,max_prospects,status,created_at,attempts,result_json,completed_at,reviewed_at FROM life_opportunity_agent_jobs WHERE tenant_id=? ORDER BY created_at DESC,id DESC LIMIT 30');$q->execute([$tenant]);$jobs=[];foreach($q->fetchAll(PDO::FETCH_ASSOC)as$r){$r['query']=$r['query_text'];unset($r['query_text']);$r['maxProspects']=(int)$r['max_prospects'];unset($r['max_prospects']);$r['attempts']=(int)$r['attempts'];$r['result']=$r['result_json']!==''?json_decode($r['result_json'],true):null;unset($r['result_json']);$jobs[]=$r;}
  return ['configured'=>count($tokens)>0,'connected'=>$last!==''&&$last>$this->at($this->time()-300),'lastSeen'=>$last,'counts'=>$counts,'jobs'=>$jobs,'scope'=>'Public company research proposals only','notice'=>'Agent results require review. No automatic outreach, applications or CV access.'];
 }
 private function queue(array $args):array {
  $pipelines=$args['pipelines']??[$args['pipeline']??''];if(!is_array($pipelines)||!array_is_list($pipelines)||count($pipelines)<1||count($pipelines)>4)throw new LifeError('Choose up to four research agents.');$pipelines=array_values(array_unique($pipelines));foreach($pipelines as$p)if(!in_array($p,['nysc','freelance','career','ai-testing'],true))throw new LifeError('Choose a valid research agent.');$query=LifeStore::text($args['query']??$args['instruction']??'',1000,true);$max=$args['maxProspects']??3;if(!is_int($max)||$max<1||$max>5)throw new LifeError('Request one to five prospects per agent.');
  return $this->transaction(function()use($pipelines,$query,$max){$db=$this->os->store->db;$tenant=$this->os->store->tenantId;$q=$db->prepare('SELECT COUNT(*) FROM life_opportunity_agent_jobs WHERE tenant_id=? AND status IN (?,?)');$q->execute([$tenant,'queued','leased']);if((int)$q->fetchColumn()+count($pipelines)>20)throw new LifeError('Review or finish the existing research queue first.',429);$q=$db->prepare('SELECT COUNT(*) FROM life_opportunity_agent_jobs WHERE tenant_id=?');$q->execute([$tenant]);if((int)$q->fetchColumn()+count($pipelines)>500)throw new LifeError('Research history limit reached.',429);$jobs=[];foreach($pipelines as$p){$id=LifeStore::id();$at=$this->at();$db->prepare('INSERT INTO life_opportunity_agent_jobs VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$id,$tenant,$p,$query,$max,'queued',$at,'','',0,'','','','']);$jobs[]=['id'=>$id,'pipeline'=>$p,'query'=>$query,'maxProspects'=>$max,'status'=>'queued','createdAt'=>$at];}return ['jobs'=>$jobs,'notice'=>'Public research queued. An authenticated worker must be connected to run it. Results need review before saving.'];});
 }
 private function authenticate(string $authorization):array {
  if(!preg_match('/^Bearer ([a-f0-9]{64})$/D',$authorization,$m))throw new LifeError('Research connection authentication required.',401);$q=$this->os->store->db->prepare('SELECT * FROM life_opportunity_agent_tokens WHERE token_hash=? AND revoked_at=? AND expires_at>?');$q->execute([hash('sha256',$m[1]),'',$this->at()]);$r=$q->fetch(PDO::FETCH_ASSOC);if(!$r||!hash_equals($r['token_hash'],hash('sha256',$m[1])))throw new LifeError('Research connection is invalid or expired.',401);return $r;
 }
 public function poll(string $authorization,array $args):array {
  $auth=$this->authenticate($authorization);$limit=$args['limit']??4;if(!is_int($limit)||$limit<1||$limit>4)throw new LifeError('Claim up to four research jobs.');
  return $this->transaction(function()use($auth,$limit){$db=$this->os->store->db;$now=$this->at();$q=$db->prepare('UPDATE life_opportunity_agent_tokens SET last_seen=? WHERE token_hash=? AND (last_seen=? OR last_seen<=?)');$q->execute([$now,$auth['token_hash'],'',$this->at($this->time()-10)]);if($q->rowCount()!==1)throw new LifeError('Check the research queue at most once every ten seconds.',429);
   $db->prepare('UPDATE life_opportunity_agent_jobs SET status=?,completed_at=? WHERE tenant_id=? AND status=? AND lease_until<=? AND attempts>=3')->execute(['failed',$now,$auth['tenant_id'],'leased',$now]);
   $q=$db->prepare('SELECT * FROM life_opportunity_agent_jobs WHERE tenant_id=? AND (status=? OR (status=? AND lease_until<=?)) AND attempts<3 ORDER BY created_at,id LIMIT 20');$q->execute([$auth['tenant_id'],'queued','leased',$now]);$jobs=[];foreach($q->fetchAll(PDO::FETCH_ASSOC)as$r){if(count($jobs)>=$limit)break;$lease=bin2hex(random_bytes(32));$until=$this->at($this->time()+600);$u=$db->prepare('UPDATE life_opportunity_agent_jobs SET status=?,lease_until=?,lease_hash=?,attempts=attempts+1 WHERE id=? AND tenant_id=? AND attempts=? AND (status=? OR (status=? AND lease_until<=?))');$u->execute(['leased',$until,hash('sha256',$lease),$r['id'],$auth['tenant_id'],$r['attempts'],'queued','leased',$now]);if($u->rowCount()!==1)continue;$jobs[]=['id'=>$r['id'],'pipeline'=>$r['pipeline'],'query'=>$r['query_text'],'maxProspects'=>(int)$r['max_prospects'],'leaseToken'=>$lease,'leaseUntil'=>$until];}
   return ['jobs'=>$jobs,'serverTime'=>$now,'scope'=>'public-company-research-only'];
  });
 }
 public static function proposals(mixed $input,int $max):array {
  if(!is_array($input)||!array_is_list($input)||count($input)>$max)throw new LifeError('Return a bounded list of research proposals.');$out=[];$seen=[];
  foreach($input as$p){if(!is_array($p))throw new LifeError('Use structured research proposals.');$company=$p['company']??[];if(is_string($company))$company=['name'=>$company];if(!is_array($company))throw new LifeError('Add the company name.');$c=['name'=>LifeStore::text($company['name']??'',200,true),'about'=>LifeStore::text($company['about']??'',2000),'industry'=>LifeStore::text($company['industry']??'',100),'website'=>LifeApplications::url($company['website']??'')];$role=LifeStore::text($p['role']??'',200,true);$sources=$p['sources']??[];if(!is_array($sources)||!array_is_list($sources)||count($sources)<1||count($sources)>15)throw new LifeError('Each proposal needs one to fifteen sources.');$cleanSources=[];foreach($sources as$s){if(!is_array($s))throw new LifeError('Use structured sources.');$url=LifeApplications::url($s['url']??'');if($url==='')throw new LifeError('Source links are required.');$cleanSources[]=['url'=>$url,'title'=>LifeStore::text($s['title']??'Source',300,true),'claim'=>LifeStore::text($s['claim']??'',2000,true)];}
   $contacts=$p['contacts']??[];if(!is_array($contacts)||!array_is_list($contacts)||count($contacts)>2)throw new LifeError('Use at most two named contacts.');$cleanContacts=[];foreach($contacts as$contact){if(!is_array($contact))throw new LifeError('Use structured contacts.');$url=LifeApplications::url($contact['sourceUrl']??'');$email=LifeStore::text($contact['email']??'',254);$evidence=LifeStore::text($contact['emailEvidence']??'',2000);if($url===''||!in_array($url,array_column($cleanSources,'url'),true))throw new LifeError('Contacts need a cited source.');if($email!==''&&(!filter_var($email,FILTER_VALIDATE_EMAIL)||!str_contains($evidence,$email)))throw new LifeError('Only explicitly published professional emails are allowed.');$linkedin=LifeApplications::url($contact['linkedin']??'');if($linkedin!==''&&!preg_match('~^https://(?:www\.)?linkedin\.com/in/[^\s]+$~i',$linkedin))throw new LifeError('Use a professional LinkedIn profile link.');$cleanContacts[]=['name'=>LifeStore::text($contact['name']??'',200,true),'role'=>LifeStore::text($contact['role']??'',200,true),'email'=>$email,'linkedin'=>$linkedin,'sourceUrl'=>$url,'emailEvidence'=>$evidence];}
   $notes=[];$inputNotes=is_array($p['notes']??null)?$p['notes']:[];foreach(['recentNews','problem','fit']as$f)$notes[$f]=LifeStore::text($p[$f]??$inputNotes[$f]??'',2000);$key=strtolower($c['name'].'|'.$role);if(isset($seen[$key]))throw new LifeError('Duplicate company and role in this research result.');$seen[$key]=true;$out[]=['company'=>$c,'role'=>$role,'contacts'=>$cleanContacts,'notes'=>$notes,'sources'=>$cleanSources,'stage'=>'researched','acceptance'=>'unknown','requiresReview'=>true];
  }return $out;
 }
 public function result(string $authorization,array $args):array {
  $auth=$this->authenticate($authorization);$id=LifeApplications::id($args['jobId']??'');$lease=$args['leaseToken']??'';if(!is_string($lease)||!preg_match('/^[a-f0-9]{64}$/D',$lease))throw new LifeError('A current research lease is required.',403);
  return $this->transaction(function()use($auth,$id,$lease,$args){$db=$this->os->store->db;$q=$db->prepare('SELECT * FROM life_opportunity_agent_jobs WHERE id=? AND tenant_id=?');$q->execute([$id,$auth['tenant_id']]);$r=$q->fetch(PDO::FETCH_ASSOC);if(!$r)throw new LifeError('Research job is unavailable.',404);if(!hash_equals($r['lease_hash'],hash('sha256',$lease)))throw new LifeError('This research lease is no longer valid.',403);$error=LifeStore::text($args['error']??'',500);$proposals=$error===''?self::proposals($args['proposals']??[],(int)$r['max_prospects']):[];$result=['proposals'=>$proposals,'error'=>$error,'requiresReview'=>true];$json=json_encode($result,JSON_THROW_ON_ERROR);if(strlen($json)>150000)throw new LifeError('Research result is too large.');$hash=hash('sha256',$json);
   if(in_array($r['status'],['completed','failed','reviewed','rejected'],true)){if($r['result_hash']!==''&&hash_equals($r['result_hash'],$hash))return ['jobId'=>$id,'status'=>$r['status'],'duplicate'=>true];throw new LifeError('This job already has a different result.',409);}
   if($r['status']!=='leased'||$r['lease_until']<=$this->at())throw new LifeError('Research lease expired. Claim the job again.',409);$status=$error===''?'completed':'failed';$u=$db->prepare('UPDATE life_opportunity_agent_jobs SET status=?,result_json=?,result_hash=?,completed_at=? WHERE id=? AND tenant_id=? AND status=? AND lease_hash=?');$u->execute([$status,$json,$hash,$this->at(),$id,$auth['tenant_id'],'leased',$r['lease_hash']]);if($u->rowCount()!==1)throw new LifeError('This research job changed. Retry safely.',409);return ['jobId'=>$id,'status'=>$status,'duplicate'=>false,'notice'=>'Proposal stored for review. No Life records were changed.'];
  });
 }
}
/** External dispatcher authenticates before constructing tenant models or creating schema. */
function life_opportunity_agents_external(string $action,PDO $db,array $input,string $authorization):array {
 if(!in_array($action,['opportunity-agents.poll','opportunity-agents.result'],true))throw new LifeError('Research action unavailable.',400);
 if(!preg_match('/^Bearer ([a-f0-9]{64})$/D',$authorization,$m))throw new LifeError('Research connection authentication required.',401);
 try{$q=$db->prepare('SELECT tenant_id FROM life_opportunity_agent_tokens WHERE token_hash=? AND revoked_at=? AND expires_at>?');$q->execute([hash('sha256',$m[1]),'',gmdate('Y-m-d\TH:i:s\Z')]);$tenant=$q->fetchColumn();}catch(PDOException){throw new LifeError('Research bridge is not configured.',503);}
 if(!$tenant)throw new LifeError('Research connection is invalid or expired.',401);$bridge=new LifeOpportunityAgents(new LifeAyoOS(new LifeStore($db,(int)$tenant)));return $action==='opportunity-agents.poll'?$bridge->poll($authorization,$input):$bridge->result($authorization,$input);
}
